describe('SyncEngine: start, probe and long-poll', () => {
  it('REQ-CONN-001 REQ-SYNC-001 starts offline, probes with wait=0, then long-polls with wait=25', async () => {
    const { engine, fake } = setup()
    engine.start()
    expect(engine.getConnection()).toBe('offline')
    await tick()
    let call = fake.only()
    expect(call.method).toBe('GET')
    expect(query(call)).toEqual({ after: '0', wait: '0' })
    expect(call.headers['X-Chat-User']).toBe('Alice')
    syncOk(call)
    await tick()
    expect(engine.getConnection()).toBe('online')
    call = fake.only()
    expect(query(call)).toEqual({ after: '0', wait: '25' })
    engine.stop()
  })

  it('REQ-SYNC-001 hasMore=true makes the next sync a probe', async () => {
    const { engine, fake } = setup()
    engine.start()
    await tick()
    syncOk(fake.only(), [wire({ seq: 1 })], 1, true)
    await tick()
    expect(query(fake.only())).toEqual({ after: '1', wait: '0' })
    syncOk(fake.only(), [], 1, false)
    await tick()
    expect(query(fake.only())).toEqual({ after: '1', wait: '25' })
    engine.stop()
  })

  it('REQ-PROTO-023 REQ-SYNC-003 the cursor is the response cursor, persisted with the messages before the next request', async () => {
    const { engine, fake, storage, store } = setup()
    engine.start()
    await tick()
    const m = wire({ seq: 40 })
    // The server's cursor wins, even if it differs from the last seq the client saw.
    syncOk(fake.only(), [m], 42, false)
    await tick()
    expect(query(fake.only()).after).toBe('42')
    expect(JSON.parse(storage.getItem(STORAGE_KEYS.cursor)!)).toBe(42)
    expect(JSON.parse(storage.getItem(STORAGE_KEYS.messages)!)).toHaveLength(1)
    expect(store.getSnapshot().messages[0]).toMatchObject({ id: m.id, status: 'received', seq: 40 })
    engine.stop()
  })

  it('REQ-CONN-007 start is idempotent and does nothing without an identity', async () => {
    const { engine, fake } = setup()
    engine.start()
    engine.start()
    await tick()
    expect(fake.calls).toHaveLength(1)
    engine.stop()

    const anon = setup({ identity: null })
    anon.engine.start()
    await tick()
    expect(anon.fake.calls).toHaveLength(0)
    expect(anon.engine.isRunning()).toBe(false)
  })

  it('REQ-CONN-007 REQ-ID-004 stop aborts the in-flight request and no request follows', async () => {
    const { engine, fake, store } = setup()
    engine.start()
    await tick()
    const call = fake.only()
    engine.stop()
    expect(call.signal?.aborted).toBe(true)
    // A late response is ignored.
    syncOk(call, [wire()], 5, false)
    await tick(60_000)
    expect(fake.calls).toHaveLength(1)
    expect(store.getSnapshot().cursor).toBe(0)
    expect(store.getSnapshot().messages).toHaveLength(0)
  })
})

