describe('SyncEngine: failures, backoff and reconnect', () => {
  it('REQ-CONN-003 backs off 1, 2, 4, 8, 8 s on consecutive failures', async () => {
    const { engine, fake, sleeps } = setup()
    engine.start()
    for (const ms of [1000, 2000, 4000, 8000, 8000]) {
      await tick()
      fake.only().fail()
      await tick()
      expect(sleeps.at(-1)).toBe(ms)
      await tick(ms - 1)
      expect(fake.pending()).toHaveLength(0)
      await tick(1)
    }
    expect(sleeps).toEqual([1000, 2000, 4000, 8000, 8000])
    engine.stop()
  })

  it('REQ-CONN-004 a success resets failures to 0 and sets the state online', async () => {
    const { engine, fake, sleeps } = setup()
    engine.start()
    await tick()
    fake.only().fail()
    await tick(1000)
    fake.only().fail()
    await tick(2000)
    syncOk(fake.only())
    await tick()
    expect(engine.getConnection()).toBe('online')
    fake.only().fail()
    await tick()
    expect(engine.getConnection()).toBe('offline')
    expect(sleeps).toEqual([1000, 2000, 1000])
    engine.stop()
  })

  it('REQ-CONN-004 a 4xx to a sync request is a failure that sets the state offline', async () => {
    const { engine, fake, store } = setup()
    engine.start()
    await tick()
    syncOk(fake.only(), [], 3)
    await tick()
    expect(engine.getConnection()).toBe('online')
    fake.only().respond(400, { error: { code: 'invalid_cursor', message: 'x' } })
    await tick()
    expect(engine.getConnection()).toBe('offline')
    expect(store.getSnapshot().cursor).toBe(3)
    engine.stop()
  })

  it('REQ-CONN-008 a failed sync (malformed 200) never changes the store, outbox or cursor', async () => {
    const { engine, fake, store } = setup({ cursor: 7 })
    engine.start()
    await tick()
    const before = store.getSnapshot()
    fake.only().respond(200, { messages: [wire()], cursor: '9', hasMore: false })
    await tick()
    expect(engine.getConnection()).toBe('offline')
    expect(store.getSnapshot()).toBe(before)
    engine.stop()
  })

  it('REQ-CONN-006 a GET times out after wait + 10 s', async () => {
    const { engine, fake, sleeps } = setup()
    engine.start()
    await tick()
    const probe = fake.only()
    await tick(9_999)
    expect(probe.signal?.aborted).toBe(false)
    await tick(1)
    expect(probe.signal?.aborted).toBe(true)
    expect(engine.getConnection()).toBe('offline')
    await tick(1000)
    syncOk(fake.only())
    await tick()
    const longPoll = fake.only()
    expect(query(longPoll).wait).toBe('25')
    await tick(34_999)
    expect(longPoll.signal?.aborted).toBe(false)
    expect(engine.getConnection()).toBe('online')
    await tick(1)
    expect(longPoll.signal?.aborted).toBe(true)
    expect(engine.getConnection()).toBe('offline')
    expect(sleeps).toEqual([1000, 1000])
    engine.stop()
  })

  it('REQ-CONN-002 REQ-SYNC-001 on reconnect all queued messages are flushed first, then a probe sync upserts them', async () => {
    const { engine, fake, store, sleeps } = setup()
    engine.send('Bob', 'one')
    engine.send('Bob', 'two')
    engine.start()
    await tick()
    fake.only().fail()
    await tick()
    expect(sleeps).toEqual([1000])
    await tick(1000)
    const echoes: unknown[] = []
    for (const body of ['one', 'two']) {
      const call = fake.only()
      expect(call.method).toBe('POST')
      expect(bodyOf(call)).toBe(body)
      const seq = ack(call)
      echoes.push({ ...(call.body as object), seq, receivedAt: '2026-10-15T10:00:05.000Z' })
      await tick()
    }
    const sync = fake.only()
    expect(sync.method).toBe('GET')
    // A failure happened since the last successful sync, so this is a probe even though POSTs succeeded.
    expect(query(sync).wait).toBe('0')
    const fromBob = wire({ from: 'Bob', to: 'Alice', seq: 50 })
    syncOk(sync, [...echoes, fromBob], 50, false)
    await tick()
    const messages = store.getSnapshot().messages
    expect(messages).toHaveLength(3)
    expect(messages.filter((m) => m.status === 'sent')).toHaveLength(2)
    expect(messages.find((m) => m.id === fromBob.id)?.status).toBe('received')
    expect(query(fake.only()).wait).toBe('25')
    engine.stop()
  })

  it('REQ-SYNC-002 REQ-SYNC-005 merge from the engine: upsert by id, failed messages untouched, cursor advances', async () => {
    const failed = local({ status: 'failed', errorCode: 'id_conflict', body: 'mine' })
    const { engine, fake, store } = setup({ messages: [failed], outbox: [] })
    engine.start()
    await tick()
    const clash = wire({ id: failed.id, from: 'Bob', to: 'Alice', body: 'theirs', seq: 10 })
    const other = wire({ from: 'Alice', to: 'Carol', seq: 11 })
    syncOk(fake.only(), [clash, other], 11, false)
    await tick()
    const snap = store.getSnapshot()
    expect(snap.cursor).toBe(11)
    expect(snap.messages).toHaveLength(2)
    expect(snap.messages.find((m) => m.id === failed.id)).toEqual(failed)
    expect(snap.messages.find((m) => m.id === other.id)?.status).toBe('sent')
    engine.stop()
  })
})

describe('SyncEngine: wake', () => {
  it('REQ-CONN-005 wake interrupts the backoff sleep without resetting failures', async () => {
    const { engine, fake, sleeps } = setup()
    engine.start()
    await tick()
    fake.only().fail()
    await tick()
    expect(sleeps).toEqual([1000])
    engine.wake()
    await tick()
    // A new cycle started immediately, without advancing time.
    const retry = fake.only()
    expect(query(retry).wait).toBe('0')
    retry.fail()
    await tick()
    expect(sleeps).toEqual([1000, 2000])
    engine.stop()
  })

  it('REQ-CONN-005 wake aborts a long-poll immediately, even if fetch never settles; the abort is not a failure', async () => {
    const { engine, fake, store, sleeps } = setup()
    engine.start()
    await tick()
    syncOk(fake.only(), [], 4)
    await tick()
    const longPoll = fake.only()
    expect(query(longPoll).wait).toBe('25')
    engine.wake()
    expect(longPoll.signal?.aborted).toBe(true)
    await tick()
    // FakeFetch never settles aborted calls, so the engine must not wait for it.
    const next = fake.only()
    expect(next).not.toBe(longPoll)
    expect(engine.getConnection()).toBe('online')
    expect(sleeps).toEqual([])
    // probe and hasMore are unchanged: still a long-poll.
    expect(query(next)).toEqual({ after: '4', wait: '25' })
    // A response that arrives after the abort is discarded.
    syncOk(longPoll, [wire()], 99, false)
    await tick()
    expect(store.getSnapshot().cursor).toBe(4)
    expect(store.getSnapshot().messages).toHaveLength(0)
    engine.stop()
  })

  it('REQ-CONN-005 wake aborts a probe without making it a failure', async () => {
    const { engine, fake, sleeps } = setup()
    engine.start()
    await tick()
    const probe = fake.only()
    engine.wake()
    await tick()
    expect(probe.signal?.aborted).toBe(true)
    expect(query(fake.only()).wait).toBe('0')
    expect(engine.getConnection()).toBe('offline')
    expect(sleeps).toEqual([])
    engine.stop()
  })

  it('REQ-CONN-009 a wake during Phase A does not interrupt the POST and starts a new cycle afterwards', async () => {
    const { engine, fake } = setup()
    engine.send('Bob', 'one')
    engine.start()
    await tick()
    const post = fake.only()
    engine.wake()
    engine.wake()
    expect(post.signal?.aborted).toBe(false)
    ack(post)
    await tick()
    // Exactly one sync request follows, issued by the new cycle.
    const sync = fake.only()
    expect(sync.method).toBe('GET')
    expect(fake.calls).toHaveLength(2)
    engine.stop()
  })

  it('REQ-CONN-009 a wake latched before the backoff skips the sleep; failures still increment', async () => {
    const { engine, fake, sleeps } = setup()
    engine.send('Bob', 'one')
    engine.start()
    await tick()
    const post = fake.only()
    engine.wake()
    post.fail()
    await tick()
    // No sleep: immediate retry.
    expect(sleeps).toEqual([])
    const retry = fake.only()
    expect(retry.method).toBe('POST')
    retry.fail()
    await tick()
    // failures was incremented by the skipped backoff: the next sleep is 2 s.
    expect(sleeps).toEqual([2000])
    engine.stop()
  })
})
